def minSubsetSumGap(nums, goal):
    def subset_sums(arr):
        sums = [0]
        for v in arr:
            sums += [s + v for s in sums]
        sums.sort()
        return sums

    mid = len(nums) // 2
    left = subset_sums(nums[:mid])
    right = subset_sums(nums[mid:])
    best = abs(goal)
    j = len(right) - 1
    for x in left:
        while j >= 0 and x + right[j] > goal:
            j -= 1
        if j >= 0:
            best = min(best, goal - x - right[j])
        if j + 1 < len(right):
            best = min(best, x + right[j + 1] - goal)
    return best
